/**
 * Generate a plan: a property plan says how it is paid, and this writes its parts on Instalments.
 *
 * WHAT A PERSON FILLS ON THE PLAN. "Make the parts" (equal parts, a down payment then equal parts, or a mortgage paid
 * monthly) and "First part on". For equal parts it also takes "Parts" and "How often"; with a down payment it takes
 * "Down payment" as well, and "Parts" then counts the parts after it. The price comes from the plan's Price, and a
 * mortgage from its Loan, Yearly rate and Years. Nothing is written until the way and the first day are both there.
 *
 * WHAT IT WRITES. One part for each date, on Instalments, linked to this plan, money out, open, from the plan's
 * account when it has one. Rounding goes to the last part, so the parts always add up to the price. A mortgage is
 * paid in equal monthly amounts, the last one taking what rounding left. The plan then loses the choices it was made
 * from, and says what happened in "What happened".
 *
 * IT NEVER ADDS TO A PLAN THAT HAS PARTS. Two runs would make the plan twice, so a plan with any part says so and is
 * left as it is. At most 120 parts.
 */
const every = { monthly: 1, quarterly: 3, half_yearly: 6, yearly: 12 };
const isDay = (v) => typeof v === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(v);
const money = (m) => m && typeof m === 'object' && Number.isSafeInteger(m.amount) && typeof m.currency === 'string' && m.amount > 0;

function addMonths(day, k) {
  const y = Number(day.slice(0, 4));
  const m = Number(day.slice(5, 7)) - 1;
  const d = Number(day.slice(8, 10));
  const at = m + k;
  const y2 = y + Math.floor(at / 12);
  const m2 = ((at % 12) + 12) % 12;
  const last = new Date(Date.UTC(y2, m2 + 1, 0)).getUTCDate();
  return String(y2).padStart(4, '0') + '-' + String(m2 + 1).padStart(2, '0') + '-' + String(Math.min(d, last)).padStart(2, '0');
}

/** What each of `n` equal monthly payments is, and what is paid in all, for a loan at a yearly rate in percent. */
function mortgage(principal, rate, n) {
  const r = rate / 100 / 12;
  const each = r === 0 ? Math.round(principal / n) : Math.round((principal * r) / (1 - Math.pow(1 + r, -n)));
  const parts = [];
  let left = principal;
  for (let i = 1; i <= n; i++) {
    const interest = Math.round(left * r);
    const pay = i === n ? left + interest : each;
    parts.push(pay);
    left = left + interest - pay;
  }
  return parts;
}

export default async function run(ctx) {
  const id = ctx.input && ctx.input.id;
  if (!id) return;
  const plan = await ctx.record.get(id);
  if (!plan || plan.register !== 'plans') return;
  const f = plan.fields;
  const how = f.make_how;
  const first = f.make_first;
  if (!how || !isDay(first)) return;
  const say = (said) => ctx.update('plans#' + plan.seq, { make_how: null, make_first: null, make_parts: null, make_every: null, make_down: null, plan_said: said }, plan.version);

  const named = await ctx.record.list('installments', { all: [{ field: 'plan', is: f.name }] });
  const linked = await ctx.record.list('installments', { all: [{ field: 'plan_row', is: plan.id }] });
  if (named.length + linked.length > 0) return say('This plan already has parts, so none were made. Remove them first, or add the missing ones on Instalments.');

  let amounts = [];
  let currency = null;
  let step = every[f.make_every] || 1;
  const count = Number.isInteger(f.make_parts) ? f.make_parts : 0;
  let monthly = null;
  if (how === 'mortgage') {
    const loan = f.mortgage_principal;
    const years = f.mortgage_years;
    if (!money(loan) || !Number.isInteger(years) || years < 1 || typeof f.mortgage_rate !== 'number') return say('A mortgage needs the loan, the yearly rate and the years on the plan.');
    currency = loan.currency;
    step = 1;
    amounts = mortgage(loan.amount, f.mortgage_rate, years * 12);
    monthly = { amount: amounts[0], currency };
  } else {
    const price = f.price;
    if (!money(price)) return say('Say the price on the plan first.');
    currency = price.currency;
    const down = how === 'down_equal' ? f.make_down : null;
    if (how === 'down_equal' && (!money(down) || down.currency !== currency || down.amount >= price.amount)) return say('The down payment must be in the price currency and less than the price.');
    if (count < 1) return say('Say how many parts.');
    const rest = how === 'down_equal' ? price.amount - down.amount : price.amount;
    const base = Math.floor(rest / count);
    const equal = [];
    for (let i = 1; i <= count; i++) equal.push(i === count ? rest - base * (count - 1) : base);
    amounts = how === 'down_equal' ? [down.amount].concat(equal) : equal;
  }
  if (amounts.length > 120) return say('That is more than 120 parts. Make fewer, or paste the plan.');

  const account = typeof f.account === 'string' && f.account !== '' ? { account: f.account } : {};
  amounts.forEach((amount, i) => {
    /* A down payment falls on the first day and the equal parts follow it one step apart. */
    const k = how === 'down_equal' ? (i === 0 ? 0 : i * step) : i * step;
    ctx.write('installments', {
      what: f.name + ', part ' + (i + 1) + ' of ' + amounts.length,
      plan: f.name,
      plan_row: plan.id,
      number: i + 1,
      parts: amounts.length,
      direction: 'out',
      amount: { amount, currency },
      due: addMonths(first, k),
      state: 'open',
      ...account,
    });
  });
  const patch = { make_how: null, make_first: null, make_parts: null, make_every: null, make_down: null, plan_said: 'Made ' + amounts.length + ' parts from ' + first + '.' };
  if (monthly) {
    patch.mortgage_monthly = monthly;
    patch.mortgage_interest = { amount: amounts.reduce((a, b) => a + b, 0) - f.mortgage_principal.amount, currency };
  }
  ctx.update('plans#' + plan.seq, patch, plan.version);
}

/**
 * Paste a plan: a payment plan copied from a spreadsheet or a contract becomes the plan's parts on Instalments.
 *
 * WHAT A PERSON PASTES. One part to a line, as a date, an amount and optionally a name, separated by tabs, semicolons
 * or commas ("2027-01-15, 125000, Down payment"). A date is year-month-day, or day first with slashes, dots or
 * dashes (15/01/2027). An amount may carry a currency sign or thousands marks; an amount with commas in it goes in
 * quotes when commas separate the line. A first line that does not start with a date is the heading and is skipped.
 *
 * WHAT IT WRITES. One part for each good line, on Instalments, linked to this plan, money out, open, from the plan's
 * account when it has one, numbered by date. The amounts are in the plan's price currency (or its value's, or its
 * loan's). A line it cannot read is left out and counted in "What happened". The pasted text is then cleared.
 *
 * IT NEVER ADDS TO A PLAN THAT HAS PARTS, as Generate a plan does not. At most 120 parts.
 */
function cells(line) {
  const sep = line.includes('\t') ? '\t' : line.includes(';') ? ';' : ',';
  const out = [];
  let cur = '';
  let quoted = false;
  for (const ch of line) {
    if (ch === '"') quoted = !quoted;
    else if (ch === sep && !quoted) {
      out.push(cur.trim());
      cur = '';
    } else cur += ch;
  }
  out.push(cur.trim());
  return out;
}

function dayOf(text) {
  let y, m, d;
  let hit = /^(\d{4})-(\d{1,2})-(\d{1,2})$/.exec(text);
  if (hit) [y, m, d] = [hit[1], hit[2], hit[3]];
  else {
    hit = /^(\d{1,2})[/.-](\d{1,2})[/.-](\d{4})$/.exec(text);
    if (!hit) return null;
    [d, m, y] = [hit[1], hit[2], hit[3]];
  }
  const at = new Date(Date.UTC(Number(y), Number(m) - 1, Number(d)));
  if (at.getUTCFullYear() !== Number(y) || at.getUTCMonth() !== Number(m) - 1 || at.getUTCDate() !== Number(d)) return null;
  return String(y).padStart(4, '0') + '-' + String(m).padStart(2, '0') + '-' + String(d).padStart(2, '0');
}

/** Minor units from "1,250,000.50", "E£ 1.250.000,50" or "125000", or null. */
function minorOf(text) {
  let t = text.replace(/[^0-9.,-]/g, '');
  if (!/[0-9]/.test(t)) return null;
  const neg = t.startsWith('-');
  t = t.replace(/-/g, '');
  const dot = t.lastIndexOf('.');
  const comma = t.lastIndexOf(',');
  const at = Math.max(dot, comma);
  let whole = t;
  let frac = '';
  if (at >= 0 && t.length - at - 1 >= 1 && t.length - at - 1 <= 2) {
    whole = t.slice(0, at);
    frac = t.slice(at + 1);
  }
  whole = whole.replace(/[.,]/g, '');
  if (whole === '' && frac === '') return null;
  const n = Number(whole || '0') * 100 + Number((frac + '00').slice(0, 2));
  return Number.isSafeInteger(n) ? (neg ? -n : n) : null;
}

export default async function run(ctx) {
  const id = ctx.input && ctx.input.id;
  if (!id) return;
  const plan = await ctx.record.get(id);
  if (!plan || plan.register !== 'plans') return;
  const f = plan.fields;
  if (typeof f.paste !== 'string' || f.paste.trim() === '') return;
  const say = (said) => ctx.update('plans#' + plan.seq, { paste: null, plan_said: said }, plan.version);

  const named = await ctx.record.list('installments', { all: [{ field: 'plan', is: f.name }] });
  const linked = await ctx.record.list('installments', { all: [{ field: 'plan_row', is: plan.id }] });
  if (named.length + linked.length > 0) return say('This plan already has parts, so nothing was pasted in. Remove them first, or add the missing ones on Instalments.');
  const known = [f.price, f.value, f.mortgage_principal].find((m) => m && typeof m.currency === 'string');
  if (!known) return say('Say the price on the plan first, so the pasted amounts have a currency.');

  const lines = f.paste.split(/\r?\n/).filter((l) => l.trim() !== '');
  const good = [];
  let skipped = 0;
  lines.forEach((line, i) => {
    const c = cells(line);
    const due = dayOf(c[0] || '');
    const amount = minorOf(c[1] || '');
    if (!due || amount === null || amount <= 0) {
      if (!(i === 0 && !due)) skipped++;
      return;
    }
    good.push({ due, amount, label: c.slice(2).filter((x) => x !== '').join(', ') });
  });
  if (good.length === 0) return say('No line could be read. Each line is a date, an amount and optionally a name.');
  if (good.length > 120) return say('That is more than 120 parts. Paste it in two plans.');
  good.sort((a, b) => (a.due < b.due ? -1 : a.due > b.due ? 1 : 0));
  const account = typeof f.account === 'string' && f.account !== '' ? { account: f.account } : {};
  good.forEach((p, i) => {
    ctx.write('installments', {
      what: p.label !== '' ? p.label : f.name + ', part ' + (i + 1) + ' of ' + good.length,
      plan: f.name,
      plan_row: plan.id,
      number: i + 1,
      parts: good.length,
      direction: 'out',
      amount: { amount: p.amount, currency: known.currency },
      due: p.due,
      state: 'open',
      ...account,
    });
  });
  say('Pasted ' + good.length + ' parts' + (skipped > 0 ? ', and left out ' + skipped + ' line' + (skipped === 1 ? '' : 's') + ' it could not read' : '') + '.');
}

/**
 * What a property plan comes to: what is paid, what is left, what the property is worth beyond that, and the total
 * of its parts paid so far at each paid part, which the page draws as a line.
 *
 * STARTED WITH A PART OR A PLAN when one is written, and once a day for every plan. For each plan that has a price or
 * a value it works through the parts that are not cancelled, earliest first, in the currency of the plan's value
 * (else its price, else its loan): the paid parts add up to "Paid" and, running, to "Paid in all" on each paid part;
 * the open parts add up to "Left to pay"; and the value less what is left is the "Equity". A part in another
 * currency is left out, since two currencies are never added. A mortgage's monthly amount and the interest over its
 * years are worked out the same way Generate a plan works them.
 *
 * It writes a field only where it would change, so it starts nothing again. Plans and parts are read a page at a time, past fifty.
 */
function mortgage(principal, rate, n) {
  const r = rate / 100 / 12;
  const each = r === 0 ? Math.round(principal / n) : Math.round((principal * r) / (1 - Math.pow(1 + r, -n)));
  let left = principal;
  let total = 0;
  for (let i = 1; i <= n; i++) {
    const interest = Math.round(left * r);
    const pay = i === n ? left + interest : each;
    total += pay;
    left = left + interest - pay;
  }
  return { each, total };
}

const money = (m) => m && typeof m === 'object' && typeof m.amount === 'number' && typeof m.currency === 'string';
const same = (a, b) => (a === undefined || a === null ? b === null : money(a) && b !== null && a.amount === b.amount && a.currency === b.currency);

/**
 * Every row of a list that `where` lets through. A script's list is one page of fifty, in the list's own order and with
 * no cursor, so the rows are asked for by number instead: the top number is found by asking above the highest seen,
 * then (0, top] is cut in halves until each half comes back short. At most 60 reads; `short` says some were left.
 */
async function every(ctx, register, where) {
  const PAGE = 50;
  const READS = 60;
  let reads = 0;
  const ask = (above, upto) => {
    reads += 1;
    const parts = [...(where ? [where] : []), ...(above > 0 ? [{ field: 'seq', gt: above }] : []), ...(upto === null ? [] : [{ field: 'seq', lte: upto }])];
    return parts.length === 0 ? ctx.record.list(register) : ctx.record.list(register, parts.length === 1 ? parts[0] : { all: parts });
  };
  const first = await ask(0, null);
  if (first.length < PAGE) return first;
  const seen = new Map(first.map((r) => [r.id, r]));
  let top = Math.max(...first.map((r) => r.seq));
  for (;;) {
    if (reads >= READS) break;
    const above = await ask(top, null);
    for (const r of above) seen.set(r.id, r);
    if (above.length < PAGE) break;
    top = Math.max(...above.map((r) => r.seq));
  }
  const spans = [[0, top]];
  let short = false;
  while (spans.length > 0) {
    if (reads >= READS) {
      short = true;
      break;
    }
    const [a, b] = spans.pop();
    const page = await ask(a, b);
    for (const r of page) seen.set(r.id, r);
    if (page.length >= PAGE && b - a > 1) {
      const mid = Math.floor((a + b) / 2);
      spans.push([a, mid], [mid, b]);
    }
  }
  const rows = [...seen.values()];
  rows.short = short;
  return rows;
}

async function work(ctx, plan) {
  const f = plan.fields;
  const mine = new Map();
  for (const p of await every(ctx, 'installments', { all: [{ field: 'plan_row', is: plan.id }] })) mine.set(p.id, p);
  for (const p of await every(ctx, 'installments', { all: [{ field: 'plan', is: f.name }] })) mine.set(p.id, p);
  const parts = [...mine.values()].filter((p) => p.fields.state !== 'cancelled' && money(p.fields.amount));
  const base = [f.value, f.price, f.mortgage_principal].find(money) || (parts[0] && parts[0].fields.amount);
  if (!base) return;
  const currency = base.currency;
  parts.sort((a, b) => (a.fields.due < b.fields.due ? -1 : a.fields.due > b.fields.due ? 1 : (a.fields.number || 0) - (b.fields.number || 0)));
  let paid = 0;
  let left = 0;
  for (const p of parts) {
    if (p.fields.amount.currency !== currency) continue;
    let next = null;
    if (p.fields.state === 'paid') {
      paid += p.fields.amount.amount;
      next = { amount: paid, currency };
    } else left += p.fields.amount.amount;
    if (!same(p.fields.paid_to_date, next)) ctx.update('installments#' + p.seq, { paid_to_date: next }, p.version);
  }
  const patch = {};
  const set = (key, value) => {
    if (!same(f[key], value)) patch[key] = value;
  };
  const any = parts.some((p) => p.fields.amount.currency === currency);
  set('paid', any ? { amount: paid, currency } : null);
  set('left', any ? { amount: left, currency } : null);
  set('equity', money(f.value) && f.value.currency === currency && any ? { amount: f.value.amount - left, currency } : null);
  const loan = f.mortgage_principal;
  if (money(loan) && typeof f.mortgage_rate === 'number' && Number.isInteger(f.mortgage_years) && f.mortgage_years > 0) {
    const m = mortgage(loan.amount, f.mortgage_rate, f.mortgage_years * 12);
    set('mortgage_monthly', { amount: m.each, currency: loan.currency });
    set('mortgage_interest', { amount: m.total - loan.amount, currency: loan.currency });
  } else {
    set('mortgage_monthly', null);
    set('mortgage_interest', null);
  }
  if (Object.keys(patch).length > 0) ctx.update('plans#' + plan.seq, patch, plan.version);
}

export default async function run(ctx) {
  const id = ctx.input && ctx.input.id;
  let plans;
  if (id) {
    const row = await ctx.record.get(id);
    if (!row) return;
    if (row.register === 'plans') plans = [row];
    else if (row.register === 'installments') {
      const link = row.fields.plan_row;
      const text = row.fields.plan;
      const found = typeof link === 'string' && link !== '' ? [await ctx.record.get(link)] : typeof text === 'string' ? await ctx.record.list('plans', { all: [{ field: 'name', is: text }] }) : [];
      plans = found.filter((p) => p && p.register === 'plans');
    } else return;
  } else plans = await every(ctx, 'plans', null);
  for (const plan of plans) {
    const f = plan.fields;
    if (money(f.value) || money(f.price) || money(f.mortgage_principal)) await work(ctx, plan);
  }
}
